                cy.wait(2000);
                P1.savee();
                cy.wait(1500);
                P1.checkErrormessage(value[3], value[4], value[5]);
                cy.wait(1500);
                cy.contains('Cancel').click();
                P1.profilepreview();
              }
            } else {
              cy.log("This contact is already present");
              cy.get('button[class="chakra-button css-ez23ye"]').click();
              P1.profilepreview();
            }
          });
